select account_type, status, case when balance >= 65000 then 'high' when balance >= 30000 then 'mid' else 'low' end as balance_bucket, avg(balance) as avg_balance, max(balance) - min(balance) as balance_range, round((100 * sum(case when status = 'FROZEN' then 1 else 0 end)) / count(*), 1) as pct_frozen from accounts where status in ('FROZEN', 'CLOSED', 'OPEN') group by account_type, status, balance_bucket order by balance_range, account_type, status, balance_bucket limit 1;
